import { useEffect, useState } from "react";
import { getPetPhotos } from "../services";

import firstImage from "../img/firstumage.png";
import doubleImage from "../img/doubleimage.png";
import tripleImage from "../img/tripleimage.png";
import lastImage from "../img/lastimage.png";

function PetsSection() {
  const [photos, setPhotos] = useState([]);
  const [showMore, setShowMore] = useState(false);

  useEffect(() => {
    async function loadPhotos() {
      try {
        const data = await getPetPhotos();
        setPhotos(data);
      } catch (error) {
        console.log("Не удалось загрузить фото:", error);
      }
    }

    loadPhotos();
  }, []);

  const fallbackPhotos = [
    firstImage,
    doubleImage,
    tripleImage,
    lastImage,
  ];

  const articles = [
    "Rescue pups pose as ghosts in festive photo shoot",
    "Cat interrupts morning coffee on sunny Washington morning",
    "New study finds dogs pay more attention to women",
    "Petting dogs gives health benefits, even if they are not yours",
  ];

  const visiblePhotos = showMore
    ? (photos.length ? photos : fallbackPhotos)
    : (photos.length ? photos.slice(0, 4) : fallbackPhotos);

  return (
    <section className="pets-section" id="about">
      <h2 className="pets-title">Interacting with our pets</h2>

      <div className="pets-gallery">
        {visiblePhotos.map((photo, index) => {
          const image = typeof photo === "string"
            ? photo
            : photo.webformatURL;

          return (
            <article className="pets-card" key={image}>
              <img
                src={image}
                alt={typeof photo === "string"
                  ? "Pet"
                  : photo.tags || "Pet"}
              />

              <p>
                {articles[index % articles.length]}
              </p>
            </article>
          );
        })}
      </div>

      <button
        className="pets-more"
        type="button"
        onClick={() => setShowMore(!showMore)}
      >
        {showMore ? "Show less" : "See more"}
      </button>
    </section>
  );
}

export default PetsSection;
